description:
{
  "image_category": "SIGN_ILLUSTRATION",
  "summary": "Hình ảnh minh họa 8 loại biển số R.412 (a–h) theo QCVN 41:2024/BGTVT, dùng để báo hiệu làn đường dành riêng cho từng loại xe hoặc nhóm xe.",
  "items": [
    {
      "identifier": "Biển số R.412a",
      "visual_or_geometric_features": "Biển hình chữ nhật đứng, nền xanh dương, viền trắng, có mũi tên hướng lên và hình vẽ xe buýt (ôtô khách).",
      "meaning_or_specification": "Làn đường dành riêng cho xe ôtô khách (kể cả ô tô buýt); nếu cần phân làn theo số chỗ ngồi thì ghi trên thân xe trong hình vẽ (ví dụ: “<16c”)."
    },
    {
      "identifier": "Biển số R.412b",
      "visual_or_geometric_features": "Biển hình chữ nhật đứng, nền xanh dương, viền trắng, có mũi tên hướng lên và hình vẽ xe ô tô con.",
      "meaning_or_specification": "Làn đường dành riêng cho xe ô tô con."
    },
    {
      "identifier": "Biển số R.412c",
      "visual_or_geometric_features": "Biển hình chữ nhật đứng, nền xanh dương, viền trắng, có mũi tên hướng lên và hình vẽ xe ô tô tải.",
      "meaning_or_specification": "Làn đường dành riêng cho xe ô tô tải; nếu cần phân làn theo khối lượng chuyên chở thì ghi trị số cho phép trên thân xe trong hình vẽ (ví dụ: “<3,5t”)."
    },
    {
      "identifier": "Biển số R.412d",
      "visual_or_geometric_features": "Biển hình chữ nhật đứng, nền xanh dương, viền trắng, có mũi tên hướng lên và hình vẽ xe máy.",
      "meaning_or_specification": "Làn đường dành riêng cho xe máy và xe gắn máy."
    },
    {
      "identifier": "Biển số R.412e",
      "visual_or_geometric_features": "Biển hình chữ nhật đứng, nền xanh dương, viền trắng, có mũi tên hướng lên và hình vẽ xe buýt.",
      "meaning_or_specification": "Làn đường dành cho xe buýt; nếu vạch sơn phân làn là nét đứt thì xe khác có thể đi vào nhưng phải ưu tiên xe buýt; nếu là nét liền thì xe khác không được vào."
    },
    {
      "identifier": "Biển số R.412f",
      "visual_or_geometric_features": "Biển hình chữ nhật đứng, nền xanh dương, viền trắng, có mũi tên hướng lên và hình vẽ xe ô tô (loại tổng quát).",
      "meaning_or_specification": "Làn đường dành cho các loại xe ô tô."
    },
    {
      "identifier": "Biển số R.412g",
      "visual_or_geometric_features": "Biển hình chữ nhật đứng, nền xanh dương, viền trắng, có mũi tên hướng lên và hình vẽ xe máy + xe đạp.",
      "meaning_or_specification": "Làn đường dành riêng cho xe máy (kể cả xe gắn máy) và xe đạp (kể cả các loại xe thô sơ khác)."
    },
    {
      "identifier": "Biển số R.412h",
      "visual_or_geometric_features": "Biển hình chữ nhật đứng, nền xanh dương, viền trắng, có mũi tên hướng lên và hình vẽ xe đạp.",
      "meaning_or_specification": "Làn đường dành riêng cho xe đạp (kể cả các loại xe thô sơ khác)."
    }
  ]
